import React from "react";
import { render, fireEvent, screen } from "@testing-library/react";
import userEvent from "@testing-library/user-event";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import Button from "../Button";
import * as stories from "./Card.stories";
import {
  Card,
  CardContent,
  CardMedia,
  CardTitle,
  CardActionArea,
  CardActions,
} from ".";

const { Basic } = composeStories(stories) as any;

describe("Card component", () => {
  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("can be clickable", () => {
    const callback = jest.fn();
    render(
      <Card onClick={callback}>
        <CardContent>
          <CardTitle>Title</CardTitle>
          <p>
            Lorem ipsum dolor sit lorem a amet, consectetur adipiscing elit, sed
            do eiusmod tempor incididunt ut labore.
          </p>
        </CardContent>
      </Card>
    );
    fireEvent.click(screen.getByText("Title"));
    expect(callback).toHaveBeenCalledTimes(1);
  });

  it("is tabbable when onClick is provided", async () => {
    const user = userEvent.setup();
    const callback = jest.fn();
    render(
      <Card onClick={callback}>
        <CardContent>
          <CardTitle>Title</CardTitle>
          <p>Content</p>
        </CardContent>
      </Card>
    );
    expect(screen.getByRole("button", { name: /title/i })).not.toHaveFocus();
    await user.tab();
    expect(screen.getByRole("button", { name: /title/i })).toHaveFocus();
  });

  it("can have a restrained clickable area", () => {
    const areaCallback = jest.fn();
    const btnCallback = jest.fn();
    render(
      <Card>
        <CardActionArea onClick={areaCallback}>
          <CardContent>
            <CardTitle>Title</CardTitle>
            <p>
              Lorem ipsum dolor sit lorem a amet, consectetur adipiscing elit,
              sed do eiusmod tempor incididunt ut labore.
            </p>
          </CardContent>
        </CardActionArea>
        <CardActions>
          <Button onClick={btnCallback}>Action</Button>
        </CardActions>
      </Card>
    );
    fireEvent.click(screen.getByText("Title"));
    fireEvent.click(screen.getByText("Action"));
    expect(areaCallback).toHaveBeenCalledTimes(1);
    expect(btnCallback).toHaveBeenCalledTimes(1);
  });

  it("passes through props", () => {
    render(
      <Card data-testid="card">
        <CardMedia data-testid="cardmedia" />
        <CardActionArea data-testid="cardactionarea">
          <CardContent data-testid="cardcontent">
            <CardTitle data-testid="cardtitle">Title</CardTitle>
          </CardContent>
        </CardActionArea>
        <CardActions data-testid="cardactions"></CardActions>
      </Card>
    );
    expect(screen.getByTestId("card")).toBeTruthy();
    expect(screen.getByTestId("cardmedia")).toBeTruthy();
    expect(screen.getByTestId("cardactionarea")).toBeTruthy();
    expect(screen.getByTestId("cardcontent")).toBeTruthy();
    expect(screen.getByTestId("cardtitle")).toBeTruthy();
    expect(screen.getByTestId("cardactions")).toBeTruthy();
  });
});
